head.b:skin:
/* ============================================================
   SM TRADERS — Design & Development by SynFusion
   ============================================================ */
:root {
  --green-900: #0b3d2e;
  --green-700: #126b4f;
  --green-500: #21a366;
  --green-400: #5bcf8a;

  --ink: #111816;
  --muted: #66736d;

  --surface: #ffffff;
  --surface-soft: #f5f8f6;
  --surface-dark: #0b1512;

  --border: rgba(17, 24, 22, 0.10);

  --radius-sm: 12px;
  --radius-md: 20px;
  --radius-lg: 28px;
  --radius-xl: 36px;

  --shadow-sm: 0 8px 30px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 24px 70px rgba(0, 0, 0, 0.12);

  --font-main: 'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  --z-content: 1;
  --z-header: 100;
  --z-actionbar: 150;
  --z-mobile-menu: 500;
  --z-lightbox: 1000;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
}
* {
  margin: 0;
  padding: 0;
}
html {
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}
body {
  margin: 0;
  width: 100%;
  min-width: 0;
  overflow-x: clip;
  font-family: var(--font-main);
  background-color: var(--surface-soft);
  color: var(--ink);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg, video, canvas {
  display: block;
  max-width: 100%;
  height: auto;
}
button, input, select, textarea {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  outline: none;
}
button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
a {
  color: inherit;
  text-decoration: none;
}
ul, ol {
  list-style: none;
}
h1, h2, h3, h4, h5, h6 {
  line-height: 1.15;
  letter-spacing: -0.03em;
  font-weight: 800;
  color: var(--ink);
}
p {
  color: var(--muted);
}

/* Kill Default Blogger UI & Wrappers */
#navbar-iframe, .navbar, #navbar, .blogger-attribution, .post-feeds, .feed-links,
#Attribution1, .status-msg-wrap, .blog-pager, .quickedit, .widget-item-control,
#outer-wrapper, #content-wrapper, #main-wrapper, #sidebar-wrapper, .blog-posts, .widget, .main {
  margin: 0 !important;
  padding: 0 !important;
  width: auto !important;
  max-width: none !important;
  min-width: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}
#navbar-iframe, .navbar, #navbar, .blogger-attribution, .post-feeds, .feed-links,
#Attribution1, .status-msg-wrap, .blog-pager, .quickedit, .widget-item-control {
  display: none !important;
  height: 0 !important;
  visibility: hidden !important;
}
.sm-cms-hide {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Container & Layout */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: clamp(16px, 4vw, 48px);
}
section {
  position: relative;
}
.sec-padding {
  padding-block: clamp(48px, 8vw, 112px);
}
.bg-dark {
  background-color: var(--surface-dark);
  color: #ffffff;
}
.bg-dark h1, .bg-dark h2, .bg-dark h3, .bg-dark h4 {
  color: #ffffff;
}
.bg-dark p {
  color: rgba(255, 255, 255, 0.7);
}
.bg-white {
  background-color: var(--surface);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--green-700);
}
.eyebrow::before {
  content: "";
  width: 18px;
  height: 2px;
  background: var(--green-500);
  border-radius: 2px;
  flex-shrink: 0;
}
.bg-dark .eyebrow {
  color: var(--green-400);
}

.sec-heading {
  font-size: clamp(28px, 5vw, 52px);
  margin-top: 12px;
  letter-spacing: -0.035em;
}
.sec-lead {
  margin-top: 16px;
  font-size: clamp(15px, 1.5vw, 18px);
  max-width: 60ch;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 15px;
  transition: all 0.25s ease;
  border: 1px solid transparent;
  white-space: nowrap;
  touch-action: manipulation;
}
.btn .icon-arr {
  transition: transform 0.25s ease;
  display: inline-block;
}
.btn:hover .icon-arr {
  transform: translateX(4px);
}
.btn-primary {
  background: var(--green-500);
  color: #ffffff;
  box-shadow: 0 8px 24px rgba(33, 163, 102, 0.28);
}
.btn-primary:hover {
  background: var(--green-700);
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(33, 163, 102, 0.38);
}
.btn-dark {
  background: var(--green-900);
  color: #ffffff;
}
.btn-dark:hover {
  background: var(--surface-dark);
  transform: translateY(-2px);
}
.btn-ghost {
  background: var(--surface);
  border-color: var(--border);
  color: var(--ink);
}
.btn-ghost:hover {
  border-color: var(--green-700);
  color: var(--green-700);
  transform: translateY(-2px);
}
.btn-outline-light {
  border-color: rgba(255, 255, 255, 0.3);
  color: #ffffff;
}
.btn-outline-light:hover {
  border-color: #ffffff;
  background: rgba(255, 255, 255, 0.1);
}
.btn-block {
  width: 100%;
}

/* Top Announcement Bar */
.top-announce {
  background: var(--green-900);
  color: rgba(255, 255, 255, 0.9);
  font-size: 13px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.top-announce .container {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 38px;
  text-align: center;
}
.top-announce b {
  color: var(--green-400);
}
.top-announce a {
  color: #ffffff;
  font-weight: 700;
  display: none;
  align-items: center;
  gap: 4px;
}
.top-announce a:hover {
  color: var(--green-400);
}

/* Navbar */
.navbar-sticky {
  position: sticky;
  top: 0;
  z-index: var(--z-header);
  background: rgba(245, 248, 246, 0.92);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid transparent;
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}
.navbar-sticky.stuck {
  background: rgba(255, 255, 255, 0.96);
  border-bottom-color: var(--border);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.04);
}
.navbar-sticky .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 68px;
  gap: 16px;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand-mark {
  width: 42px;
  height: 42px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--green-900), var(--green-700));
  color: var(--green-400);
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 16px;
  box-shadow: 0 6px 16px rgba(11, 61, 46, 0.25);
}
.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}
.brand-text strong {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--ink);
}
.brand-text span {
  font-size: 11px;
  color: var(--muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 4px;
}
.nav-links a {
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 14.5px;
  font-weight: 600;
  color: var(--ink);
  transition: background 0.2s ease, color 0.2s ease;
}
.nav-links a:hover {
  background: var(--border);
}
.nav-links a.active {
  background: rgba(33, 163, 102, 0.12);
  color: var(--green-700);
  font-weight: 700;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-actions .btn {
  display: none;
}

.burger-btn {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}
.burger-btn span {
  display: block;
  width: 18px;
  height: 2px;
  background-color: var(--ink);
  border-radius: 2px;
  transition: transform 0.3s ease, opacity 0.2s ease;
}

/* Mobile Drawer Overlay */
.mobile-drawer {
  position: fixed;
  inset: 0;
  z-index: var(--z-mobile-menu);
  background: var(--surface-dark);
  color: #ffffff;
  display: flex;
  flex-direction: column;
  padding: 20px clamp(18px, 5vw, 36px) calc(28px + env(safe-area-inset-bottom));
  opacity: 0;
  visibility: hidden;
  transform: translateY(-12px);
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0.3s;
  overflow-y: auto;
}
.mobile-drawer.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.drawer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
}
.drawer-top strong {
  font-size: 18px;
  font-weight: 800;
  color: #ffffff;
}
.drawer-close {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: grid;
  place-items: center;
  color: #ffffff;
  font-size: 24px;
}
.drawer-nav {
  display: flex;
  flex-direction: column;
  margin-top: 24px;
  flex: 1;
}
.drawer-nav a {
  padding: 16px 4px;
  font-size: 20px;
  font-weight: 700;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.drawer-nav a span {
  color: var(--green-400);
  font-size: 16px;
}
.mobile-drawer .btn {
  margin-top: 28px;
}
body.lock-scroll {
  overflow: hidden;
}

/* Hero Section */
.hero-sec {
  padding-block: clamp(32px, 6vw, 72px) clamp(48px, 8vw, 96px);
  background: radial-gradient(80% 60% at 85% 15%, rgba(33, 163, 102, 0.12), transparent 70%),
              radial-gradient(60% 50% at 10% 85%, rgba(11, 61, 46, 0.08), transparent 70%);
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(32px, 5vw, 64px);
  align-items: center;
}
.hero-content h1 {
  font-size: clamp(34px, 7vw, 64px);
  margin-top: 16px;
  letter-spacing: -0.04em;
  font-weight: 900;
}
.hero-content h1 span.gradient-text {
  background: linear-gradient(135deg, var(--green-900), var(--green-500));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  display: block;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}
.hero-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 28px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--border);
  font-size: 13px;
  font-weight: 700;
  box-shadow: var(--shadow-sm);
}
.chip i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green-500);
  display: block;
}

.hero-visual {
  position: relative;
  width: 100%;
}
.hero-card-visual {
  position: relative;
  width: 100%;
  aspect-ratio: 4/3;
  border-radius: var(--radius-xl);
  overflow: hidden;
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  background: linear-gradient(145deg, var(--green-900), var(--surface-dark));
}
.hero-card-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.visual-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  text-align: center;
  padding: 24px;
  background:
    radial-gradient(circle at 30% 30%, rgba(33, 163, 102, 0.25), transparent 60%),
    linear-gradient(145deg, var(--green-900), var(--surface-dark));
  color: rgba(255, 255, 255, 0.85);
}
.visual-placeholder svg {
  width: 48px;
  height: 48px;
  stroke: var(--green-400);
  fill: none;
  stroke-width: 1.5;
}
.visual-placeholder strong {
  color: #ffffff;
  font-size: 18px;
  letter-spacing: 0.05em;
}

.float-badge {
  position: absolute;
  background: rgba(255, 255, 255, 0.95);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  padding: 12px 16px;
  z-index: 10;
}
.float-badge-a {
  left: 12px;
  bottom: -16px;
}
.float-badge-a b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--green-700);
  font-weight: 800;
  text-transform: uppercase;
}
.float-badge-a p {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  margin-top: 2px;
}
.float-badge-b {
  right: 12px;
  top: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.float-badge-b .brand-mark {
  width: 36px;
  height: 36px;
  font-size: 13px;
}

/* Trust Bar */
.trust-bar {
  background: var(--surface-dark);
  color: #ffffff;
  padding-block: 28px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.trust-item {
  padding: 12px;
  border-left: 2px solid var(--green-500);
}
.trust-item b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--green-400);
  font-weight: 800;
}
.trust-item p {
  margin-top: 4px;
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
}

/* Services Grid */
.services-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.card-service {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  overflow: hidden;
}
.card-service::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--green-500), var(--green-400));
  opacity: 0;
  transition: opacity 0.3s ease;
}
.card-service:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: rgba(33, 163, 102, 0.3);
}
.card-service:hover::before {
  opacity: 1;
}
.service-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: rgba(33, 163, 102, 0.1);
  color: var(--green-700);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.service-icon svg {
  width: 26px;
  height: 26px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.card-service h3 {
  font-size: 20px;
}
.card-service p {
  font-size: 14.5px;
}
.card-service .card-link {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  font-size: 14px;
  color: var(--green-700);
}

/* Dark Solar Section & Diagram */
.solar-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(32px, 5vw, 64px);
  align-items: center;
}
.solar-diagram-box {
  margin-top: 28px;
  background: var(--surface-dark);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.diagram-title {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--green-400);
  text-transform: uppercase;
  margin-bottom: 16px;
}
.solar-flow {
  display: flex;
  flex-direction: column;
  gap: 0;
  width: 100%;
}
.flow-step {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-sm);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #ffffff;
}
.flow-step span {
  color: var(--green-400);
  font-size: 11px;
  background: rgba(33, 163, 102, 0.15);
  padding: 4px 8px;
  border-radius: 999px;
}
.flow-connector {
  width: 2px;
  height: 20px;
  margin-inline: auto;
  background: linear-gradient(var(--green-500), rgba(33, 163, 102, 0.2));
}

/* Process Timeline */
.process-timeline {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  margin-top: 40px;
}
.process-card {
  position: relative;
  padding-left: 36px;
  border-left: 2px solid rgba(255, 255, 255, 0.15);
}
.process-card::before {
  content: "";
  position: absolute;
  left: -7px;
  top: 0;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--green-400);
  box-shadow: 0 0 0 4px rgba(33, 163, 102, 0.25);
}
.process-num {
  font-size: 12px;
  font-weight: 900;
  color: var(--green-400);
  letter-spacing: 0.15em;
}
.process-card h3 {
  font-size: 18px;
  margin-top: 4px;
}
.process-card p {
  font-size: 14px;
  margin-top: 4px;
}

/* Portfolio Section */
.portfolio-filters {
  display: flex;
  overflow-x: auto;
  max-width: 100%;
  gap: 8px;
  margin-top: 28px;
  padding-bottom: 8px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.portfolio-filters::-webkit-scrollbar {
  display: none;
}
.filter-btn {
  flex: 0 0 auto;
  padding: 10px 20px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--surface);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.05em;
  transition: all 0.25s ease;
  white-space: nowrap;
}
.filter-btn.active {
  background: var(--green-900);
  color: #ffffff;
  border-color: var(--green-900);
}

.portfolio-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 28px;
}
.project-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  text-align: left;
  width: 100%;
}
.project-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.project-thumb {
  width: 100%;
  aspect-ratio: 4/3;
  background: var(--surface-dark);
  position: relative;
  overflow: hidden;
}
.project-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.project-card:hover .project-thumb img {
  transform: scale(1.05);
}
.project-content {
  padding: 20px;
}
.project-tag {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--green-700);
  text-transform: uppercase;
}
.project-content h3 {
  font-size: 18px;
  margin-top: 6px;
}
.project-content p {
  font-size: 14px;
  margin-top: 6px;
}
.project-card-hidden {
  display: none !important;
}

/* Lightbox */
.lightbox-modal {
  position: fixed;
  inset: 0;
  z-index: var(--z-lightbox);
  background: rgba(11, 21, 18, 0.95);
  display: none;
  flex-direction: column;
  padding: 20px;
}
.lightbox-modal.open {
  display: flex;
}
.lightbox-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #ffffff;
}
.lightbox-header h3 {
  color: #ffffff;
  font-size: 16px;
}
.lightbox-close {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  font-size: 24px;
  display: grid;
  place-items: center;
}
.lightbox-body {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 20px 0;
  overflow: hidden;
}
.lightbox-body img {
  max-width: 100%;
  max-height: 75vh;
  border-radius: var(--radius-md);
  object-fit: contain;
}
.lightbox-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  padding-bottom: env(safe-area-inset-bottom);
}
.lightbox-controls button {
  min-width: 48px;
  min-height: 48px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  font-size: 18px;
}

/* Owner Profiles Section */
.owners-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 28px;
  margin-top: 40px;
}
.owner-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  position: relative;
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.owner-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.owner-portrait-area {
  width: 100%;
  aspect-ratio: 4/5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  background: linear-gradient(145deg, var(--green-900), var(--surface-dark));
}
.owner-portrait-area img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.owner-initials {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  font-size: clamp(48px, 10vw, 72px);
  font-weight: 900;
  color: var(--green-400);
  background:
    radial-gradient(circle at 50% 30%, rgba(33, 163, 102, 0.25), transparent 70%),
    linear-gradient(145deg, var(--green-900), var(--surface-dark));
}
.owner-info {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.role-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(33, 163, 102, 0.12);
  color: var(--green-700);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.15em;
  align-self: flex-start;
}
.role-badge i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green-500);
}
.owner-info h3 {
  font-size: clamp(22px, 3vw, 28px);
}
.owner-company {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--muted);
  text-transform: uppercase;
}
.owner-focus {
  font-size: 14px;
  font-weight: 700;
  color: var(--green-700);
}
.owner-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}
.owner-tags span {
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
}

/* Why SM Traders Grid */
.why-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  margin-top: 40px;
}
.why-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}
.why-card h3 {
  font-size: 18px;
  margin-top: 12px;
}
.why-card p {
  font-size: 14px;
  margin-top: 6px;
}

/* Products Grid */
.products-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
  margin-top: 40px;
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.product-card h3 {
  font-size: 18px;
}
.product-card p {
  font-size: 14px;
}
.product-card a {
  margin-top: auto;
  font-size: 13px;
  font-weight: 800;
  color: var(--green-700);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* FAQ Accordion */
.faq-accordion {
  margin-top: 36px;
  border-top: 1px solid var(--border);
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  text-align: left;
  font-size: clamp(16px, 2vw, 19px);
  font-weight: 700;
  gap: 16px;
  color: var(--ink);
}
.faq-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  font-size: 18px;
  flex-shrink: 0;
  transition: transform 0.3s ease, background 0.3s ease;
}
.faq-item.open .faq-icon {
  transform: rotate(45deg);
  background: var(--green-500);
  color: #ffffff;
  border-color: var(--green-500);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.faq-answer p {
  padding-bottom: 20px;
  font-size: 15px;
}

/* Contact CTA & Form */
.contact-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 36px;
  margin-top: 40px;
}
.contact-info-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.contact-info-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-md);
  padding: 18px 20px;
}
.contact-info-card b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--green-400);
  text-transform: uppercase;
}
.contact-info-card p {
  margin-top: 4px;
  font-size: 15px;
  color: #ffffff;
}

.form-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: clamp(20px, 4vw, 36px);
  box-shadow: var(--shadow-lg);
}
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.form-group label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.form-group input, .form-group select, .form-group textarea {
  width: 100%;
  min-height: 48px;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-soft);
  font-size: 16px; /* 16px prevents mobile browser zoom */
  color: var(--ink);
  transition: border-color 0.2s ease;
}
.form-group textarea {
  min-height: 110px;
  resize: vertical;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  border-color: var(--green-500);
}
.form-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
}

/* Mobile Sticky Bottom Action Bar */
.mobile-action-bar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: var(--z-actionbar);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  background: rgba(11, 21, 18, 0.96);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding-bottom: env(safe-area-inset-bottom);
}
.mobile-action-bar a {
  min-height: 56px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
}
.mobile-action-bar a + a {
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}
.mobile-action-bar svg {
  width: 18px;
  height: 18px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
}
.mobile-action-bar a:last-child {
  color: var(--green-400);
}

/* Footer */
.footer {
  background: var(--surface-dark);
  color: rgba(255, 255, 255, 0.7);
  padding-block: clamp(48px, 6vw, 80px) calc(88px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.footer-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 32px;
}
.footer h4 {
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.footer ul li {
  margin-bottom: 10px;
  font-size: 14px;
}
.footer a:hover {
  color: var(--green-400);
}
.footer-bottom {
  margin-top: 40px;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
  font-size: 13px;
}
.footer-bottom em {
  font-style: normal;
  color: var(--green-400);
  font-weight: 700;
}

/* Animations */
.fade-up {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}
.fade-up.in {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive Breakpoints */
@media (min-width: 480px) {
  .form-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .top-announce a {
    display: inline-flex;
  }
}

@media (min-width: 600px) {
  .services-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .portfolio-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .why-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .products-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 768px) {
  .trust-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .contact-grid {
    grid-template-columns: 1fr 1.2fr;
  }
  .footer-grid {
    grid-template-columns: 1.5fr 1fr 1fr 1fr;
  }
  .owner-card {
    grid-template-columns: 220px minmax(0, 1fr);
  }
}

@media (min-width: 900px) {
  .products-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .why-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (min-width: 1024px) {
  html {
    scroll-padding-top: 100px;
  }
  .nav-links {
    display: flex;
  }
  .burger-btn {
    display: none;
  }
  .nav-actions .btn {
    display: inline-flex;
  }
  .hero-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  }
  .solar-grid {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
  .solar-flow {
    flex-direction: row;
    align-items: center;
  }
  .flow-connector {
    width: 24px;
    height: 2px;
    background: linear-gradient(90deg, var(--green-500), rgba(33, 163, 102, 0.2));
  }
  .process-timeline {
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 16px;
  }
  .process-card {
    padding-left: 0;
    padding-top: 24px;
    border-left: 0;
    border-top: 2px solid rgba(255, 255, 255, 0.15);
  }
  .process-card::before {
    left: 0;
    top: -7px;
  }
  .services-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .portfolio-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .owners-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .owner-card {
    grid-template-columns: 220px minmax(0, 1fr);
  }
  .mobile-action-bar {
    display: none;
  }
  .footer {
    padding-bottom: clamp(48px, 6vw, 80px);
  }
}

@media (max-width: 1023px) {
  body {
    padding-bottom: calc(56px + env(safe-area-inset-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .fade-up {
    opacity: 1;
    transform: none;
  }
}

body.script:
//
  (function () {
    "use strict";

    /* Central Configuration Object */
    var SM_CONFIG = {
      businessName: "SM Traders",
      owners: [
        {
          name: "Mangesh Yendhe",
          role: "OWNER",
          focus: "Electrical & Solar Solutions",
          image: "MANGESH_PROFILE_IMAGE_URL",
          initials: "MY",
          tags: ["Electrical", "Solar", "Installation"],
          bio: "Hands-on electrical professional leading major electrical installations, rooftop solar projects, and commercial power distribution."
        },
        {
          name: "Omkar Yendhe",
          role: "CO-FOUNDER",
          focus: "Electrical & Solar Solutions",
          image: "OMKAR_PROFILE_IMAGE_URL",
          initials: "OY",
          tags: ["Electrical", "Solar", "Service"],
          bio: "Co-founding partner overseeing site management, client service coordination, and technical maintenance execution."
        }
      ],
      phone: "+91 98765 43210",
      whatsapp: "919876543210",
      heroImage: "HERO_IMAGE_URL",
      solarImage: "SOLAR_IMAGE_URL",
      projects: [
        { title: "Rooftop Solar Installation", category: "solar residential", desc: "Turnkey residential solar panels setup with grid connectivity.", image: "PROJECT_1_IMAGE_URL" },
        { title: "Commercial Power Distribution", category: "electrical commercial", desc: "Main MCB/RCCB distribution board installation for commercial complex.", image: "PROJECT_2_IMAGE_URL" },
        { title: "Full House Wiring Project", category: "electrical residential", desc: "Concealed house wiring with branded copper cables and modular switches.", image: "PROJECT_3_IMAGE_URL" },
        { title: "Commercial LED Lighting Setup", category: "electrical commercial", desc: "Architectural LED lighting layout for retail store.", image: "PROJECT_4_IMAGE_URL" },
        { title: "Solar Inverter Room Wiring", category: "solar commercial", desc: "High-capacity solar inverter and safety SPD box installation.", image: "PROJECT_5_IMAGE_URL" },
        { title: "Inverter & Battery Backup", category: "electrical residential", desc: "Heavy-duty home inverter setup with automated switchover.", image: "PROJECT_6_IMAGE_URL" }
      ],
      products: [
        { title: "Wires & Cables", desc: "ISI-certified multi-strand copper cables and weather-resistant outdoor wires." },
        { title: "Switches & Sockets", desc: "Modular switches, safety sockets, fan regulators, and cover plates." },
        { title: "MCB / RCCB", desc: "Single/three-phase MCBs, RCCB protection units, and distribution enclosures." },
        { title: "LED Lighting", desc: "Indoor LED panels, surface lights, floodlights, and decorative strip lights." },
        { title: "Inverter & Batteries", desc: "Home inverters, solar hybrid inverters, and high-capacity tubular batteries." },
        { title: "Solar Components", desc: "Solar panels, mounting structures, DC cables, and solar protection boxes." }
      ],
      faq: [
        { q: "What electrical services does SM Traders provide?", a: "We provide complete electrical installation, concealed house wiring, DB board upgrades, MCB/RCCB protection, inverter setup, LED lighting, and repair services." },
        { q: "Do you install rooftop solar?", a: "Yes, we handle rooftop solar installation end-to-end, including site evaluation, structural mounting, solar panel wiring, inverter setup, and grid integration." },
        { q: "Do you handle residential work?", a: "Yes, we undertake all types of residential electrical wiring, repair, and backup power projects for apartments and individual houses." },
        { q: "Do you handle commercial work?", a: "Yes, we specialize in commercial electrical distribution, showroom lighting layouts, and commercial solar installations." },
        { q: "How can I request a quotation?", a: "You can click 'Get a Quote' or contact us via WhatsApp or Phone to share your requirements for a prompt estimate." },
        { q: "Do you provide maintenance?", a: "Yes, we offer ongoing electrical maintenance and solar system support after installation." }
      ]
    };

    var $ = function (s, c) { return (c || document).querySelector(s); };
    var $$ = function (s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); };
    var isUrlValid = function (url) { return url && !/_URL$/.test(url) && /^https?:\/\//i.test(url); };

    function buildWaUrl(msg) {
      var num = SM_CONFIG.whatsapp.replace(/[^0-9]/g, "");
      var text = encodeURIComponent(msg || "Hello SM Traders, I would like to enquire about your services.");
      return "https://wa.me/" + num + "?text=" + text;
    }

    /* Owner Rendering */
    function renderOwners() {
      var container = $("#ownersGrid");
      if (!container) return;

      container.innerHTML = SM_CONFIG.owners.map(function (owner) {
        var portraitHtml = isUrlValid(owner.image)
          ? '<img src="' + owner.image + '" alt="' + owner.name + '" loading="lazy"/>'
          : '<div class="owner-initials">' + owner.initials + '</div>';

        var tagsHtml = owner.tags.map(function (t) { return '<span>' + t + '</span>'; }).join('');

        return '<article class="owner-card fade-up">' +
          '<div class="owner-portrait-area">' + portraitHtml + '</div>' +
          '<div class="owner-info">' +
            '<span class="role-badge"><i/>' + owner.role + '</span>' +
            '<h3>' + owner.name + '</h3>' +
            '<span class="owner-company">SM TRADERS</span>' +
            '<div class="owner-focus">' + owner.focus + '</div>' +
            '<p>' + owner.bio + '</p>' +
            '<div class="owner-tags">' + tagsHtml + '</div>' +
          '</div>' +
        '</article>';
      }).join('');
    }

    /* Products Rendering */
    function renderProducts() {
      var container = $("#productsGrid");
      if (!container) return;

      container.innerHTML = SM_CONFIG.products.map(function (prod) {
        var waMsg = "Hello SM Traders, I want to enquire about product supply for: " + prod.title;
        return '<article class="product-card fade-up">' +
          '<h3>' + prod.title + '</h3>' +
          '<p>' + prod.desc + '</p>' +
          '<a href="' + buildWaUrl(waMsg) + '" target="_blank" rel="noopener">ENQUIRE SUPPLIES <span class="icon-arr">&#8594;</span></a>' +
        '</article>';
      }).join('');
    }

    /* Portfolio Rendering & Filtering */
    var currentProjects = [];
    function renderPortfolio() {
      var container = $("#portfolioGrid");
      if (!container) return;

      currentProjects = SM_CONFIG.projects;
      container.innerHTML = currentProjects.map(function (p, index) {
        var thumbHtml = isUrlValid(p.image)
          ? '<img src="' + p.image + '" alt="' + p.title + '" loading="lazy"/>'
          : '<div class="visual-placeholder"><svg viewBox="0 0 24 24" style="width:32px;height:32px;stroke:var(--green-400)"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg></div>';

        return '<button class="project-card fade-up" type="button" data-index="' + index + '" data-cat="' + p.category + '">' +
          '<div class="project-thumb">' + thumbHtml + '</div>' +
          '<div class="project-content">' +
            '<span class="project-tag">' + p.category.split(' ')[0] + '</span>' +
            '<h3>' + p.title + '</h3>' +
            '<p>' + p.desc + '</p>' +
          '</div>' +
        '</button>';
      }).join('');
    }

    function initPortfolioFilters() {
      var filterBar = $("#portfolioFilters");
      if (!filterBar) return;

      filterBar.addEventListener("click", function (e) {
        var btn = e.target.closest(".filter-btn");
        if (!btn) return;

        $$(".filter-btn", filterBar).forEach(function (b) { b.classList.remove("active"); });
        btn.classList.add("active");

        var filter = btn.getAttribute("data-filter");
        $$("#portfolioGrid .project-card").forEach(function (card) {
          var cat = card.getAttribute("data-cat") || "";
          if (filter === "all" || cat.indexOf(filter) !== -1) {
            card.classList.remove("project-card-hidden");
          } else {
            card.classList.add("project-card-hidden");
          }
        });
      });
    }

    /* Lightbox Modal */
    var lightboxState = { index: 0, open: false };
    function openLightbox(index) {
      var modal = $("#lightboxModal");
      if (!modal || !currentProjects.length) return;

      lightboxState.index = (index + currentProjects.length) % currentProjects.length;
      var p = currentProjects[lightboxState.index];

      var titleEl = $("#lightboxTitle");
      var imgEl = $("#lightboxImg");

      if (titleEl) titleEl.textContent = p.title;
      if (imgEl) {
        imgEl.src = isUrlValid(p.image) ? p.image : 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600"><rect width="800" height="600" fill="#0b1512"/><text x="400" y="300" fill="#5bcf8a" font-family="sans-serif" font-size="24" text-anchor="middle">SM TRADERS — ' + p.title + '</text></svg>');
      }

      modal.classList.add("open");
      document.body.classList.add("lock-scroll");
      lightboxState.open = true;
    }

    function closeLightbox() {
      var modal = $("#lightboxModal");
      if (!modal) return;
      modal.classList.remove("open");
      document.body.classList.remove("lock-scroll");
      lightboxState.open = false;
    }

    function initLightbox() {
      var grid = $("#portfolioGrid");
      if (grid) {
        grid.addEventListener("click", function (e) {
          var card = e.target.closest(".project-card");
          if (card) {
            var idx = parseInt(card.getAttribute("data-index"), 10) || 0;
            openLightbox(idx);
          }
        });
      }

      var closeBtn = $("#lightboxClose");
      var prevBtn = $("#lightboxPrev");
      var nextBtn = $("#lightboxNext");
      var modal = $("#lightboxModal");

      if (closeBtn) closeBtn.addEventListener("click", closeLightbox);
      if (prevBtn) prevBtn.addEventListener("click", function () { openLightbox(lightboxState.index - 1); });
      if (nextBtn) nextBtn.addEventListener("click", function () { openLightbox(lightboxState.index + 1); });

      if (modal) {
        modal.addEventListener("click", function (e) {
          if (e.target === modal) closeLightbox();
        });
      }
    }

    /* FAQ Accordion */
    function renderFaq() {
      var container = $("#faqAccordion");
      if (!container) return;

      container.innerHTML = SM_CONFIG.faq.map(function (item, i) {
        return '<div class="faq-item">' +
          '<button class="faq-question" type="button" aria-expanded="false" aria-controls="faq-ans-' + i + '">' +
            '<span>' + item.q + '</span>' +
            '<span class="faq-icon">+</span>' +
          '</button>' +
          '<div class="faq-answer" id="faq-ans-' + i + '">' +
            '<p>' + item.a + '</p>' +
          '</div>' +
        '</div>';
      }).join('');

      container.addEventListener("click", function (e) {
        var btn = e.target.closest(".faq-question");
        if (!btn) return;

        var item = btn.parentNode;
        var ans = item.querySelector(".faq-answer");
        var isOpen = item.classList.contains("open");

        $$(".faq-item", container).forEach(function (fi) {
          fi.classList.remove("open");
          fi.querySelector(".faq-question").setAttribute("aria-expanded", "false");
          fi.querySelector(".faq-answer").style.maxHeight = "0px";
        });

        if (!isOpen) {
          item.classList.add("open");
          btn.setAttribute("aria-expanded", "true");
          ans.style.maxHeight = ans.scrollHeight + "px";
        }
      });
    }

    /* Mobile Drawer Navigation */
    function initNavigation() {
      var burger = $("#burgerBtn");
      var drawer = $("#mobileDrawer");
      var drawerClose = $("#drawerClose");
      var navbar = $("#navbar");

      function toggleDrawer(open) {
        if (!drawer) return;
        drawer.classList.toggle("open", open);
        document.body.classList.toggle("lock-scroll", open);
        if (burger) burger.setAttribute("aria-expanded", open ? "true" : "false");
      }

      if (burger) burger.addEventListener("click", function () { toggleDrawer(true); });
      if (drawerClose) drawerClose.addEventListener("click", function () { toggleDrawer(false); });

      if (drawer) {
        drawer.addEventListener("click", function (e) {
          if (e.target.closest("a")) toggleDrawer(false);
        });
      }

      document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
          if (lightboxState.open) closeLightbox();
          if (drawer && drawer.classList.contains("open")) toggleDrawer(false);
        }
      });

      window.addEventListener("scroll", function () {
        if (navbar) {
          if (window.scrollY > 20) {
            navbar.classList.add("stuck");
          } else {
            navbar.classList.remove("stuck");
          }
        }
      }, { passive: true });
    }

    /* Contact Links & Form */
    function initContact() {
      var callTel = "tel:" + SM_CONFIG.phone.replace(/[^0-9+]/g, "");
      var waUrl = buildWaUrl();

      var callBtn = $("#callCtaBtn");
      var waBtn = $("#waCtaBtn");
      var mobileCall = $("#mobileBarCall");
      var mobileWa = $("#mobileBarWa");

      if (callBtn) callBtn.href = callTel;
      if (waBtn) waBtn.href = waUrl;
      if (mobileCall) mobileCall.href = callTel;
      if (mobileWa) mobileWa.href = waUrl;

      var form = $("#contactForm");
      if (form) {
        form.addEventListener("submit", function (e) {
          e.preventDefault();
          var name = ($("#inputName") || {}).value || "";
          var phone = ($("#inputPhone") || {}).value || "";
          var service = ($("#selectService") || {}).value || "";
          var location = ($("#inputLocation") || {}).value || "";
          var msg = ($("#inputMsg") || {}).value || "";

          if (!name || !phone) {
            alert("Please provide your name and phone number.");
            return;
          }

          var waText = "Hello SM Traders, I have an enquiry:\n" +
            "Name: " + name + "\n" +
            "Phone: " + phone + "\n" +
            "Service: " + service + "\n" +
            "Location: " + location + "\n" +
            "Message: " + msg;

          window.open(buildWaUrl(waText), "_blank");
        });
      }
    }

    /* Scroll Reveal */
    function initScrollReveal() {
      var els = $$(".fade-up");
      if (!("IntersectionObserver" in window)) {
        els.forEach(function (el) { el.classList.add("in"); });
        return;
      }

      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
            observer.unobserve(entry.target);
          }
        });
      }, { threshold: 0.1 });

      els.forEach(function (el) { observer.observe(el); });
    }

    /* Set Year */
    function initYear() {
      var yr = $("#yearSpan");
      if (yr) yr.textContent = new Date().getFullYear();
    }

    /* Boot */
    function init() {
      renderOwners();
      renderProducts();
      renderPortfolio();
      initPortfolioFilters();
      initLightbox();
      renderFaq();
      initNavigation();
      initContact();
      initYear();
      initScrollReveal();
    }

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", init);
    } else {
      init();
    }
  })();
  //
